FMT_FUNC detail::utf8_to_utf16::utf8_to_utf16(string_view s) {
  digit_grouping<char> grouping(locale_ref(), false);
  grouping.bind_buffer_state(static_cast<unsigned long long>(s.size()));
  for_each_codepoint(s, [this, &grouping](uint32_t cp, string_view) {
    if (cp == invalid_code_point) FMT_THROW(std::runtime_error("invalid utf8"));
    grouping.append_utf16(buffer_, cp);
    return true;
  });
  buffer_.push_back(0);
}

