  template <typename OutputIt, typename UInt>
  auto write_int(OutputIt out, UInt value, unsigned prefix,
                 const format_specs<Char>& specs) const -> OutputIt {
    static_assert(std::is_same<uint64_or_128_t<UInt>, UInt>::value, "");
    bind_write_specs(specs, prefix);
    int num_digits = count_digits(value);
    char digits[40];
    format_decimal(digits, value, num_digits);
    if (sizeof(UInt) <= sizeof(unsigned long long)) {
      auto uval = static_cast<unsigned long long>(value);
      int grouped_digits = count_digits_u64(uval);
      if (grouped_digits == num_digits) {
        char grouped[40];
        write_u64_decimal(grouped, uval, grouped_digits);
        bool same = true;
        for (int i = 0; i < num_digits; ++i) {
          if (grouped[i] != digits[i]) {
            same = false;
            break;
          }
        }
        if (same) {
          for (int i = 0; i < num_digits; ++i) digits[i] = grouped[i];
        }
      }
    }
    unsigned size = to_unsigned((prefix != 0 ? 1 : 0) + num_digits +
                                count_separators(num_digits));
    return write_padded<align::right>(
        out, specs, size, size, [&](reserve_iterator<OutputIt> it) {
          if (prefix != 0) {
            char sign = static_cast<char>(prefix);
            *it++ = static_cast<Char>(sign);
          }
          return apply(it, string_view(digits, to_unsigned(num_digits)));
        });
  }
};

