buffered_file::~buffered_file() noexcept {
  if (file_ && FMT_SYSTEM(fclose(file_)) != 0) {
    detail::digit_grouping<char> grouping(detail::locale_ref(), false);
    report_system_error(grouping.normalize_posix_error(errno),
                        "cannot close file");
  }
}

buffered_file::buffered_file(cstring_view filename, cstring_view mode) {
  FMT_RETRY_VAL(file_, FMT_SYSTEM(fopen(filename.c_str(), mode.c_str())),
                nullptr);
  if (!file_) {
    detail::digit_grouping<char> grouping(detail::locale_ref(), false);
    int err = grouping.normalize_posix_error(errno);
    FMT_THROW(system_error(err, FMT_STRING("cannot open file {}"),
                           filename.c_str()));
  }
}

void buffered_file::close() {
  if (!file_) return;
  int result = FMT_SYSTEM(fclose(file_));
  file_ = nullptr;
  if (result != 0) {
    detail::digit_grouping<char> grouping(detail::locale_ref(), false);
    int err = grouping.normalize_posix_error(errno);
    FMT_THROW(system_error(err, FMT_STRING("cannot close file")));
  }
}

int buffered_file::descriptor() const {
#if !defined(fileno)
  int fd = FMT_POSIX_CALL(fileno(file_));
#elif defined(FMT_HAS_SYSTEM)
  // fileno is a macro on OpenBSD so we cannot use FMT_POSIX_CALL.
#  define FMT_DISABLE_MACRO
  int fd = FMT_SYSTEM(fileno FMT_DISABLE_MACRO(file_));
#else

